def decode_rle(input):
    """
    Gets a stream of data and decompresses it
    under a Run-Length Decoding.
    :param input: The data to be decoded.
    :return: The decoded string.
    """
    decode_str = ''
    count = ''

    for ch in input:
        # If not numerical
        if not ch.isdigit():
            # Expand it for the decoding
            decode_str += ch * int(count)
            count = ''
        else:
            # Add it in the counter
            count += ch
    return decode_str

def decode_rle_impl(input):
    decode_str = ''
    count = ''
    for ch in input:
        if not ch.isdigit():
            if count:
                decode_str += ch * int(count)
            else:
                decode_str += ch
            count = ''
        else:
            count += ch
    if count:
        decode_str += input[-1] * int(count)
    return decode_str

